div {
  background: linear-gradient(to right, red 20%, blue 80%);
}

div {
  background: repeating-linear-gradient(45deg, yellow, yellow 10px, black 10px, black 20px);
}

h1 {
  background: linear-gradient(to right, orange, purple);
  -webkit-background-clip: text;
  color: transparent;
}

.banner {
  background-image: url('photo.jpg');
  background-color: red;
  background-blend-mode: multiply;
}

:root {
  --brand: #ff0000;
}
.tag {
  background-color: rgb(from var(--brand) r g b / 0.2);
}

.mesh {
  background-color: #e5e5f7;
  background-image:
    linear-gradient(#444cf7 1px, transparent 1px),
    linear-gradient(to right, #444cf7 1px, transparent 1px);
  background-size: 20px 20px;
}

:root {
  --btn-bg: #0070f3;
}
.button {
  background: var(--btn-bg);
}
.button:hover {
  background: color-mix(in srgb, var(--btn-bg), black 15%);
}

.canvas {
  background: 
    radial-gradient(circle, red, transparent 20%),
    linear-gradient(to right, blue, green),
    #fff;
}

:root {
  --accent: #808080;
}
.highlight {
  color: rgb(from var(--accent) calc(r + 50) g b);
}

@property --stop {
  syntax: '<percentage>';
  inherits: false;
  initial-value: 0%;
}
.glow {
  background: linear-gradient(to right, red var(--stop), blue);
  transition: --stop 0.5s ease;
}

.glass-card {
  background: rgba(255, 255, 255, 0.15);
  backdrop-filter: blur(12px) saturate(180%);
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 16px;
}

.highlight {
  background: linear-gradient(to right, orange, pink);
  padding: 4px 8px;
  border-radius: 6px;
  box-decoration-break: clone;
  -webkit-box-decoration-break: clone;
}

.hero {
  background-image: 
    linear-gradient(rgba(0,0,0,0.6), rgba(0,0,0,0.6)),
    url('hero.jpg');
  background-size: cover;
  color: #ffffff;
}

/* Approach A */
.bg-a { animation: slideBg 5s linear infinite; }
@keyframes slideBg { to { background-position: -1000px 0; } }

/* Approach B */
.bg-b::before {
  content: ''; position: absolute; inset: 0;
  background-image: url('pattern.png');
  animation: slideTransform 5s linear infinite;
}
@keyframes slideTransform { to { transform: translate3d(-1000px, 0, 0); } }

.box {
  padding: 30px;
  background-origin: content-box;
  background-image: radial-gradient(at top left, red, blue);
}

.card {
  background: 
    radial-gradient(circle at 50% 50%, red, transparent),
    conic-gradient(from 45deg, yellow, green, blue);
  contain: paint;
}

:root {
  color-scheme: light dark;
}
.sidebar {
  color-scheme: dark;
  background: light-dark(#fff, #222);
  color: light-dark(#000, #eee);
}

.gradient-heading {
  color: #0070f3;
}
@supports (-webkit-background-clip: text) or (background-clip: text) {
  .gradient-heading {
    background: linear-gradient(to right, #0070f3, #f81ce5);
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
  }
}
